void PqInt8Quantizer::setup_chunk_offsets() {
  const uint32_t base_dim = original_dim_ / num_chunk_;
  const uint32_t large_chunks = original_dim_ % num_chunk_;
  chunk_offsets_.resize(static_cast<size_t>(num_chunk_) + 1);
